import itertools

# Check cycle C11
n = 11
edges = [(i, (i+1) % n) for i in range(n)]

# Check independence number
def max_independent_set(edges, n):
    # brute force for small n
    best = 0
    for r in range(n, 0, -1):
        for combo in itertools.combinations(range(n), r):
            ok = True
            for u, v in edges:
                if u in combo and v in combo:
                    ok = False
                    break
            if ok:
                return r
    return 0

alpha = max_independent_set(edges, n)
print(f"Independence number: {alpha}")

# Check vertex connectivity
# A cycle has vertex connectivity 2
# Let's verify by checking if removing any single vertex leaves the graph connected
def is_connected(edges, n, removed=None):
    if removed is None:
        vertices = list(range(n))
    else:
        vertices = [v for v in range(n) if v != removed]
    if len(vertices) <= 1:
        return True
    adj = {v: [] for v in vertices}
    for u, v in edges:
        if u in vertices and v in vertices:
            adj[u].append(v)
            adj[v].append(u)
    # BFS
    visited = set()
    stack = [vertices[0]]
    while stack:
        v = stack.pop()
        if v in visited:
            continue
        visited.add(v)
        for nb in adj[v]:
            if nb not in visited:
                stack.append(nb)
    return len(visited) == len(vertices)

kappa = n  # start high
for v in range(n):
    if not is_connected(edges, n, removed=v):
        kappa = 0
        break
else:
    # check if removing any single vertex disconnects
    # for cycle, removing any vertex leaves a path which is connected
    kappa = 2  # cycle has connectivity 2

print(f"Vertex connectivity: at least 2 (cycle)")

# Let's also check if removing any 1 vertex disconnects
for v in range(n):
    conn = is_connected(edges, n, removed=v)
    print(f"  Remove {v}: connected = {conn}")
